		    // and most used symbols that are not already declared as types.
		    "not",
		    "ref",
		    "raise",
		    "reraise",
		    "dict",
		    "readOnlyDict",
		    "set",
		    "get",
		    "enum",
		    "sizeof",
		    "typeof",
		    "typedefof",
		    "nameof",
		    "nullArg",
		    "invalidArg",
		    "invalidOp",
		    "id",
		    "fst",
		    "snd",
		    "ignore",
		    "lock",
		    "using",
		    "box",
		    "unbox",
		    "tryUnbox",
		    "printf",
		    "printfn",
		    "sprintf",
		    "eprintf",
		    "eprintfn",
		    "fprintf",
		    "fprintfn",
		    "failwith",
		    "failwithf"
