		      DISCRIMINATED_UNION_TYPE_ANNOTATION,
		      TYPE_ANNOTATION,
		      COMPUTATION_EXPRESSION,
		      PREPROCESSOR,
		      NUMBER,
		      GENERIC_TYPE_SYMBOL,
		      OPERATOR
